insert into sector_profiles (settore, version, status, pack, changelog)
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_processo', 'Cos''è l''APE?', $q1h0ulr$["cosa e l ape","cos e l ape","a cosa serve l ape","cos e l attestato di prestazione energetica","cosa significa ape","serve l ape"]$q1h0ulr$::jsonb, 'L''APE (Attestato di Prestazione Energetica) è il documento che indica la classe energetica di un immobile, cioè quanto consuma in modo convenzionale per riscaldamento, raffrescamento e acqua calda. In genere va indicata negli annunci di vendita e affitto. Per i dati di un immobile specifico faccia riferimento all''agente.', $qidbh2o${}$qidbh2o$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_processo', 'Cos''è la classe energetica?', $qdck3m2$["cosa e la classe energetica","cos e la classe energetica","cosa significa classe energetica","che cosa indica la classe energetica","cosa indica la classe energetica"]$qdck3m2$::jsonb, 'La classe energetica è una sigla che indica l''efficienza energetica dell''immobile ed è riportata nell''APE. Più la classe è efficiente, minori sono in genere i consumi previsti. La classe di un immobile specifico va verificata sull''APE o con l''agente.', $qsjip67${}$qsjip67$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_processo', 'Qual è la differenza tra compromesso e rogito?', $qule5sq$["differenza tra compromesso e rogito","che differenza c e tra compromesso e rogito","cos e il compromesso","cos e il rogito","cosa e il rogito","cosa e il compromesso","cosa significa rogito","cosa significa compromesso","differenza tra preliminare e rogito"]$qule5sq$::jsonb, 'Il compromesso (contratto preliminare) è l''accordo con cui venditore e acquirente si impegnano a concludere la compravendita a certe condizioni. Il rogito è l''atto notarile definitivo con cui la proprietà passa all''acquirente. Per gli aspetti legali del suo caso è necessario il notaio.', $q55k9hi${}$q55k9hi$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_processo', 'Cos''è una proposta d''acquisto?', $qoierpj$["cos e una proposta d acquisto","cosa e una proposta d acquisto","come funziona la proposta d acquisto","cos e la proposta di acquisto","cosa significa proposta d acquisto","come funziona la proposta di acquisto"]$qoierpj$::jsonb, 'La proposta d''acquisto è la dichiarazione scritta con cui chi vuole comprare indica l''offerta e le condizioni. Se il venditore la accetta si prosegue con i passaggi successivi, di solito il preliminare. Condizioni e tutele vanno chiarite con l''agente e, per gli aspetti legali, con il notaio.', $qdhkz5m${}$qdhkz5m$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_processo', 'Cos''è la caparra?', $q51p05h$["cos e la caparra","cosa e la caparra","cosa significa caparra","a cosa serve la caparra","cos e la caparra confirmatoria","cosa e la caparra confirmatoria"]$q51p05h$::jsonb, 'La caparra è una somma che chi compra o affitta versa a garanzia dell''accordo; le conseguenze dipendono dal tipo di caparra e da quanto previsto dal contratto. Importi e condizioni vanno chiariti con l''agente e con un professionista prima di qualsiasi pagamento: in chat non si gestiscono pagamenti.', $qknoi1n${}$qknoi1n$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_processo', 'Come funziona una valutazione immobiliare?', $q84mhg0$["come funziona una valutazione","come funziona la valutazione","come si valuta un immobile","come funziona la stima della casa","come viene valutata la casa","come si fa la valutazione dell immobile","cos e una valutazione immobiliare","come funziona la valutazione dell immobile"]$q84mhg0$::jsonb, 'Una valutazione serve a stimare il valore di un immobile: l''agente raccoglie i dati (zona, metratura, stato, caratteristiche), in genere fa un sopralluogo e confronta l''immobile con il mercato della zona. Senza questi passaggi non si può indicare una cifra, per questo in chat non posso darle stime.', $qepz9fs${}$qepz9fs$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_processo', 'Cosa sono le spese condominiali?', $q9synjv$["cosa sono le spese condominiali","cosa sono le spese di condominio","cosa comprendono le spese condominiali","cosa sono le spese condominio","cosa vuol dire spese condominiali"]$q9synjv$::jsonb, 'Le spese condominiali sono i costi di gestione delle parti comuni dell''edificio (per esempio pulizia, ascensore, illuminazione, amministratore) e si ripartiscono tra i condomini. L''importo cambia da edificio a edificio: per un immobile specifico lo comunica l''agente sulla base dei dati disponibili.', $q3r2zaq${}$q3r2zaq$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_processo', 'Cosa significano monolocale, bilocale e trilocale?', $qtb03ft$["differenza tra bilocale e trilocale","cos e un bilocale","cos e un trilocale","cosa significa bilocale","cosa significa trilocale","cos e un monolocale","differenza tra monolocale e bilocale"]$qtb03ft$::jsonb, 'Il nome indica il numero di ambienti principali: il monolocale ha un unico ambiente, il bilocale due (di solito zona giorno e camera), il trilocale tre, il quadrilocale quattro. La disposizione degli spazi cambia da immobile a immobile.', $q9c68p8${}$q9c68p8$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_processo', 'Che differenza c''è tra superficie calpestabile e commerciale?', $qg6lgdf$["differenza tra superficie calpestabile e commerciale","cos e la superficie commerciale","cos e la superficie calpestabile","cosa significa superficie commerciale","perche i metri quadri cambiano"]$qg6lgdf$::jsonb, 'La superficie calpestabile è quella effettivamente utilizzabile all''interno dell''immobile; la superficie commerciale comprende anche i muri e una quota di pertinenze (come balconi o cantine) con appositi coefficienti. Per questo i metri quadri indicati possono differire a seconda del criterio.', $q9m79jl${}$q9m79jl$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_processo', 'Cos''è la planimetria catastale e la visura?', $q8a7xbs$["cos e la planimetria","cos e la visura catastale","cosa e la planimetria catastale","cosa significa visura","cos e la visura","a cosa serve la visura catastale"]$q8a7xbs$::jsonb, 'La planimetria catastale è il disegno dell''immobile depositato al catasto; la visura catastale riporta i dati catastali (identificativi, rendita, intestatari). Sono documenti usuali nelle compravendite, e l''agente indica quali servono nel suo caso.', $q3jv1zc${}$q3jv1zc$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_processo', 'Cos''è la nuda proprietà?', $qh6qpi3$["cosa e la nuda proprieta","cos e la nuda proprieta","cosa significa nuda proprieta","cos e l usufrutto","cosa significa usufrutto"]$qh6qpi3$::jsonb, 'Nella nuda proprietà si diventa proprietari ma non si può usare l''immobile finché dura il diritto di usufrutto di un''altra persona (di solito il venditore). Condizioni e valutazioni vanno esaminate caso per caso con l''agente e con il notaio.', $qmdwxmi${}$qmdwxmi$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_processo', 'Cosa significa immobile libero o locato?', $qhtcpls$["cosa significa libero","cosa vuol dire immobile locato","cosa significa locato","cosa significa immobile libero","cosa vuol dire libero subito","cosa significa libero subito"]$qhtcpls$::jsonb, 'Un immobile "libero" non è occupato; "locato" significa che c''è già un contratto di affitto in corso con un inquilino. Se un immobile specifico sia libero o locato, e da quando, lo conferma solo l''agente.', $qdmfdde${}$qdmfdde$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_processo', 'Che tipi di contratto di affitto esistono?', $q3lbhu3$["che tipi di contratto di affitto esistono","quali contratti di affitto esistono","tipi di contratto di locazione","differenza tra canone libero e concordato","cos e il canone concordato","cos e un contratto transitorio","cos e il contratto per studenti"]$q3lbhu3$::jsonb, 'Per le abitazioni esistono diverse tipologie di contratto di locazione (per esempio a canone libero, a canone concordato, transitorio, per studenti), con durata e condizioni diverse. L''agente può spiegarle quali sono adatte alla situazione; per gli aspetti legali e fiscali serve un professionista.', $q02wyr9${}$q02wyr9$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_documenti', 'Che documenti servono per vendere casa?', $q031tog$["che documenti servono per vendere casa","documenti per vendere casa","documenti per vendere un immobile","cosa serve per vendere casa","cosa serve per mettere in vendita","che documenti servono per vendere","quali documenti per vendere l appartamento"]$q031tog$::jsonb, 'In genere servono i documenti di proprietà (titolo di provenienza), planimetria e visura catastale, l''APE e la documentazione sulla conformità urbanistica e catastale. L''agente le indica l''elenco preciso per il suo immobile.', $q6mab5a${}$q6mab5a$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_documenti', 'Che documenti servono per prendere in affitto?', $qpldmbo$["che documenti servono per affittare","cosa serve per prendere in affitto","documenti per un affitto","cosa mi serve per affittare casa","documenti per affittare","cosa serve per affittare"]$qpldmbo$::jsonb, 'In genere chi cerca in affitto presenta un documento d''identità, il codice fiscale e documenti che mostrino la capacità di sostenere il canone (per esempio contratto di lavoro o buste paga). I requisiti precisi li stabilisce il proprietario: li verifichi con l''agente.', $qrjmjyj${}$qrjmjyj$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_documenti', 'Che documenti servono per comprare casa?', $qf8zba4$["che documenti servono per comprare","documenti per comprare casa","cosa serve per comprare casa","cosa serve per acquistare un immobile","documenti per acquistare"]$qf8zba4$::jsonb, 'Per fare una proposta d''acquisto di solito bastano documento d''identità e codice fiscale. Per le fasi successive, l''agente e il notaio indicano la documentazione necessaria.', $qpm08qr${}$qpm08qr$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_mutuo', 'Cos''è un mutuo?', $q8rsqsf$["cos e un mutuo","cosa e un mutuo","come funziona il mutuo","come funziona un mutuo","cosa significa mutuo","cos e il mutuo"]$q8rsqsf$::jsonb, 'Il mutuo è un finanziamento a medio-lungo termine, di solito erogato da una banca, per acquistare un immobile e restituito a rate. Condizioni e requisiti sono stabiliti dalla banca: per capire cosa è adatto al suo caso serve un consulente o la banca stessa, io non posso fare valutazioni finanziarie.', $qyruyku${}$qyruyku$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_processo', 'Come funziona la visita a un immobile?', $q0a9urx$["come funziona la visita","come funziona la visita di un immobile","cosa succede durante la visita","come si svolge la visita","come si svolge una visita"]$q0a9urx$::jsonb, 'La visita è l''occasione per vedere l''immobile con un agente e fare domande su caratteristiche, spese e documenti. Conviene preparare in anticipo le domande più importanti. Date e disponibilità si concordano con l''agenzia.', $qre2w83${}$qre2w83$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('immobiliare', 1, 'production', 'info_processo', 'Cosa vuol dire trattativa riservata o a trattativa?', $qa2nb74$["cosa significa trattativa riservata","cosa vuol dire trattativa riservata","cos e la trattativa riservata","cosa significa prezzo a trattativa"]$qa2nb74$::jsonb, '"Trattativa riservata" indica in genere che il prezzo non è pubblicato nell''annuncio e viene comunicato su richiesta. Per un immobile specifico, prezzo e condizioni li fornisce l''agente.', $qfyp51l${}$qfyp51l$::jsonb);
